// src/components/settings/ThemeSwitch.tsx
'use client'

import { useTheme } from 'next-themes'
import { Sun, Moon } from 'lucide-react'
import { useEffect, useState } from 'react'

export function ThemeSwitch() {
  const { theme, setTheme } = useTheme()
  const [mounted, setMounted] = useState(false)

  // Pastikan komponen sudah di-mount di client sebelum menampilkan UI
  useEffect(() => setMounted(true), [])

  if (!mounted) {
    return null
  }

  return (
    <div className="bg-white dark:bg-gray-800 p-6 rounded-2xl shadow-md">
        <h3 className="text-lg font-semibold text-black-300 dark:text-gray-100 mb-4">Pengaturan Tema</h3>
        <div className="flex items-center space-x-4">
            <p className="text-sm text-gray-600 dark:text-gray-400">Mode Saat Ini: <span className="font-bold capitalize">{theme}</span></p>
            <button
                onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
                className="p-2 rounded-full bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-gray-200"
                aria-label="Toggle Dark Mode"
            >
                {theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}
            </button>
        </div>
        <button onClick={() => setTheme('system')} className="text-sm text-blue-600 hover:underline mt-4">Gunakan Pengaturan Sistem</button>
    </div>
  )
}